8	/**
9	 * Derives an owner's canonical region ({@code locality}), preferring the postcode.
10	 *
11	 * <p>The postcode range is consulted first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a
12	 * 4-digit postcode landing in a known range resolves the region directly. Only when the postcode
13	 * is absent or falls in no known range does the fixed city-to-region table apply (Sydney-&gt;NSW,
14	 * Melbourne-&gt;VIC, Brisbane-&gt;QLD). Anything unresolved by either is {@code "UNKNOWN"}.
15	 *
16	 * <p>Known cities keep the same region as before, but cities that share a name are disambiguated
17	 * by their postcode.
18	 */
19	public final class OwnerLocality {
20	
21	    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");
22	
23	    /** City -> canonical region (matching {@link RequirePostcode}'s table). */
24	    private static final Map<String, String> CITY_REGION = Map.of(
25	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
26	
27	    /** Region -> inclusive 4-digit postcode range {low, high}. */
28	    private static final Map<String, int[]> REGION_RANGE = Map.of(
29	            "NSW", new int[] {2000, 2099},
30	            "VIC", new int[] {3000, 3099},
31	            "QLD", new int[] {4000, 4099});
32	
33	    /** Region -> IANA timezone name. */
34	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
35	            "NSW", "Australia/Sydney",
36	            "VIC", "Australia/Melbourne",
37	            "QLD", "Australia/Brisbane");
38	
39	    private OwnerLocality() {
40	    }
41	
42	    /**
43	     * The locality of an already-stored owner: the REGION segment of its {@code customerCode}
44	     * identity ({@code <REGION>-<HASH8>}, see {@link AssignCustomerCode}). Falls back to deriving
45	     * the region straight from the postcode/city for an owner whose {@code customerCode} has not
46	     * been assigned or is not in the region-and-hash form.
47	     */
48	    public static String forOwner(Owner owner) {
49	        String code = owner.getCustomerCode();
50	        if (code != null) {
51	            int dash = code.indexOf('-');
52	            if (dash > 0) {
53	                return code.substring(0, dash);
54	            }
55	        }
56	        return of(owner.getCity(), owner.getPostcode());
57	    }
58	
59	    /**
60	     * The IANA timezone for an already-stored owner, derived from its {@link #forOwner(Owner)}
61	     * locality via the fixed region-to-timezone table. {@code null} when the locality resolves
62	     * to no known region (e.g. {@code "UNKNOWN"}).
63	     */
64	    public static String timezoneForOwner(Owner owner) {
65	        return REGION_TIMEZONE.get(forOwner(owner));
66	    }
67	
68	    static String of(String city, String postcode) {
69	        String byPostcode = regionForPostcode(postcode);
70	        if (byPostcode != null) {
71	            return byPostcode;
72	        }
73	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
74	    }
75	
76	    private static String regionForPostcode(String postcode) {
77	        if (postcode == null || !FOUR_DIGITS.matcher(postcode).matches()) {
78	            return null;
79	        }
80	        int value = Integer.parseInt(postcode);
81	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
82	            int[] range = entry.getValue();
83	            if (value >= range[0] && value <= range[1]) {
84	                return entry.getKey();
85	            }
86	        }
87	        return null;
88	    }
89	}
